<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class MartyrCatalogManager {
    public function __construct(private PDO $db,private array $actor){if(!Permissions::allows($db,$actor,'taxonomy.manage'))throw new HttpError(403,'مدیریت محور و مقدار به مجوز مدیر دسته‌بندی نیاز دارد.');if(!MartyrTaxonomySchema::ready($db))throw new HttpError(503,'ابتدا مدیر اصلی ارتقای دسته‌بندی را اجرا کند.');}
    private static function label(string $v):string{return preg_replace('/\s+/u',' ',Security::normalize(trim($v)));}
    private function log(string $key,mixed $before,mixed $after,string $reason):void {Db::insert($this->db,'protocol_changes',['martyr_id'=>null,'user_id'=>$this->actor['id'],'field_key'=>$key,'before_value'=>Protocol::encode($before),'after_value'=>Protocol::encode($after),'reason'=>$reason,'created_at'=>date('Y-m-d H:i:s')]);}
    public function axis(array $in):string {
        $key=Security::text($in,'axis_key',40,false);$new=$key==='';if($new)$key='custom_'.bin2hex(random_bytes(8));$existing=$new?false:Db::query($this->db,'SELECT a.*,s.* FROM taxonomy_axes a JOIN martyr_axis_settings s ON s.axis_key=a.axis_key WHERE a.axis_key=? AND a.subject=?',[$key,'martyr'])->fetch();if(!$new&&!$existing)throw new HttpError(404,'محور پیدا نشد.');$title=Security::text($in,'title',150);$mode=Security::text($in,'selection_mode',10);if(!in_array($mode,['single','multiple'],true))throw new HttpError(422,'نوع انتخاب معتبر نیست.');$step=(int)($in['form_section']??6);if($step<1||$step>7)throw new HttpError(422,'بخش فرم معتبر نیست.');
        if($existing){if((int)$existing['revision']!==(int)($in['revision']??-1))throw new HttpError(409,'تنظیمات محور تغییر کرده است.');if($mode!==$existing['selection_mode']||$step!==(int)$existing['form_section']){if(isset(MartyrCatalog::bindings()[$key])||Db::query($this->db,'SELECT id FROM protocol_terms WHERE taxonomy=? LIMIT 1',[$key])->fetchColumn())throw new HttpError(422,'نوع انتخاب و محل ثبت محور استفاده‌شده را تغییر ندهید؛ ابتدا داده‌ها باید بررسی شوند.');}}
        $group=Security::text($in,'filter_group',20,false)?:($new?'':(string)Db::query($this->db,'SELECT value FROM app_settings WHERE setting_key=?',['gallery_group_'.$key])->fetchColumn());if($group!==''&&!in_array($group,['thematic','geography','other'],true))throw new HttpError(422,'گروه نمایش فیلتر معتبر نیست.');
        $base=['title'=>$title,'active'=>!empty($in['active'])?1:0,'public_filter'=>!empty($in['public_filter'])?1:0];$settings=['description'=>Security::text($in,'description',3000,false),'selection_mode'=>$mode,'form_section'=>$step,'form_order'=>(int)($in['form_order']??0),'filter_order'=>(int)($in['filter_order']??0),'hierarchical'=>!empty($in['hierarchical'])?1:0,'show_in_form'=>!empty($in['show_in_form'])?1:0];
        return Db::transaction($this->db,function()use($key,$new,$existing,$base,$settings,$in,$group){if($new){Db::insert($this->db,'taxonomy_axes',['axis_key'=>$key,'subject'=>'martyr']+$base);Db::insert($this->db,'martyr_axis_settings',['axis_key'=>$key,'binding_kind'=>'person','binding_key'=>'axis_'.$key]+$settings);}else{Db::query($this->db,'UPDATE taxonomy_axes SET title=?,active=?,public_filter=? WHERE axis_key=?',[...array_values($base),$key]);$changed=Db::query($this->db,'UPDATE martyr_axis_settings SET '.implode(',',array_map(fn($k)=>$k.'=?',array_keys($settings))).',revision=revision+1 WHERE axis_key=? AND revision=?',[...array_values($settings),$key,(int)$in['revision']])->rowCount();if(!$changed)throw new HttpError(409,'نسخه تنظیمات محور تغییر کرده است.');}if($group!==''){$setting='gallery_group_'.$key;if(Db::query($this->db,'SELECT setting_key FROM app_settings WHERE setting_key=?',[$setting])->fetchColumn())Db::query($this->db,'UPDATE app_settings SET value=?,updated_by=?,updated_at=? WHERE setting_key=?',[$group,$this->actor['id'],date('Y-m-d H:i:s'),$setting]);else Db::insert($this->db,'app_settings',['setting_key'=>$setting,'value'=>$group,'updated_by'=>$this->actor['id'],'updated_at'=>date('Y-m-d H:i:s')]);}$this->log('axis.'.$key,$existing,$base+$settings+['filter_group'=>$group?:($key==='collection'?'thematic':'other')],'مدیریت محور');return $key;});
    }
    public function term(array $in):int {
        $axis=Security::text($in,'taxonomy',40);$geo=in_array($axis,['country','province','county','city'],true);$spec=Db::query($this->db,'SELECT a.axis_key,s.hierarchical FROM taxonomy_axes a JOIN martyr_axis_settings s ON s.axis_key=a.axis_key WHERE a.axis_key=? AND a.subject=?',[$axis,'martyr'])->fetch();if(!$spec&&!$geo)throw new HttpError(422,'محور متعلق به دسته‌بندی شهدای سامانه نیست.');$id=(int)($in['term_id']??0);$old=$id?Db::query($this->db,'SELECT * FROM protocol_terms WHERE id=? AND taxonomy=?',[$id,$axis])->fetch():false;if($id&&!$old)throw new HttpError(404,'مقدار پیدا نشد.');$title=Security::text($in,'title',200);$parent=(int)($in['parent_id']??0);if($parent){$p=Db::query($this->db,'SELECT * FROM protocol_terms WHERE id=?',[$parent])->fetch();$expected=['province'=>'country','county'=>'province','city'=>'county'][$axis]??$axis;if(!$p||$p['taxonomy']!==$expected||$parent===$id)throw new HttpError(422,'والد با محور سازگار نیست.');if(!$geo&&!$spec['hierarchical'])throw new HttpError(422,'سلسله‌مراتب برای این محور فعال نیست.');$seen=[$id];while($p){if(in_array((int)$p['id'],$seen,true))throw new HttpError(422,'چرخه در والدها مجاز نیست.');$seen[]=(int)$p['id'];$p=$p['parent_id']?Db::query($this->db,'SELECT * FROM protocol_terms WHERE id=?',[$p['parent_id']])->fetch():false;}}
        if(in_array($axis,['province','county','city'],true)&&!$parent)throw new HttpError(422,'برای این سطح جغرافیا والد لازم است.');if($old&&$geo&&(int)$old['parent_id']!==$parent)throw new HttpError(422,'والد مکان موجود را تغییر ندهید؛ برای حفظ پرونده‌های قبلی یک مکان مستقل ثبت کنید.');
        foreach(Db::query($this->db,'SELECT id,title,parent_id FROM protocol_terms WHERE taxonomy=? AND id<>?',[$axis,$id])->fetchAll() as $r)if((int)$r['parent_id']===$parent&&self::label($r['title'])===self::label($title))throw new HttpError(409,'مقدار هم‌نام در همین محور و والد موجود است؛ همان مقدار را استفاده یا ادغام کنید.');
        $slug=$old['slug']??('term_'.bin2hex(random_bytes(10)));$meta=$old?Protocol::decode($old['metadata']):[];if($axis==='rank'){$source=(int)($in['source_id']??$meta['source_id']??0);if(!$source||!Db::query($this->db,'SELECT id FROM protocol_sources WHERE id=?',[$source])->fetchColumn())throw new HttpError(422,'درجه نظامی به منبع دقیق نیاز دارد.');$meta['source_id']=$source;}if($axis==='collection'&&!isset($meta['mode']))$meta['mode']='editorial';$aliases=array_values(array_filter(array_map('trim',preg_split('/\R/u',Security::text($in,'aliases',5000,false)))));$values=['title'=>$title,'parent_id'=>$parent?:null,'sort_order'=>(int)($in['sort_order']??0),'active'=>!empty($in['active'])?1:0,'aliases'=>Protocol::encode($aliases),'metadata'=>Protocol::encode($meta)];
        return Db::transaction($this->db,function()use($id,$axis,$slug,$values,$old){if($id)Db::query($this->db,'UPDATE protocol_terms SET '.implode(',',array_map(fn($k)=>$k.'=?',array_keys($values))).' WHERE id=?',[...array_values($values),$id]);else $id=Db::insert($this->db,'protocol_terms',['taxonomy'=>$axis,'slug'=>$slug]+$values);$this->log('term.'.$id,$old,$values,'مدیریت مقدار');return $id;});
    }
    public function merge(array $in):void {
        $source=(int)($in['source_id']??0);$target=(int)($in['target_id']??0);$reason=Security::text($in,'reason',2000);if(($in['merge_ack']??'')!=='1'||!$source||!$target||$source===$target)throw new HttpError(422,'مبدأ، مقصد و تأیید صریح ادغام لازم است.');
        Db::transaction($this->db,function()use($source,$target,$reason){$lock=$this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$a=Db::query($this->db,'SELECT * FROM protocol_terms WHERE id=?'.$lock,[$source])->fetch();$b=Db::query($this->db,'SELECT * FROM protocol_terms WHERE id=?'.$lock,[$target])->fetch();if(!$a||!$b||$a['taxonomy']!==$b['taxonomy']||!$b['active'])throw new HttpError(422,'ادغام فقط بین دو مقدار یک محور و با مقصد فعال مجاز است.');if(in_array($a['taxonomy'],['country','province','county','city'],true))throw new HttpError(422,'ادغام جغرافیا به تطبیق اختصاصی و بررسی والدها نیاز دارد؛ در این فرم مجاز نیست.');if(!Db::query($this->db,'SELECT axis_key FROM martyr_axis_settings WHERE axis_key=?',[$a['taxonomy']])->fetchColumn())throw new HttpError(422,'محور خارج از بانک شهداست.');if(Db::query($this->db,'SELECT id FROM protocol_terms WHERE parent_id=? LIMIT 1',[$source])->fetchColumn())throw new HttpError(422,'مقدار دارای زیرمجموعه را ادغام نکنید؛ ابتدا ساختار والدها را جداگانه بررسی کنید.');if(MartyrCatalog::canonical($this->db,$target)===$source)throw new HttpError(422,'ادغام چرخه ایجاد می‌کند.');$old=Db::query($this->db,'SELECT * FROM martyr_term_redirects WHERE source_term_id=?',[$source])->fetch();if($old)Db::query($this->db,'UPDATE martyr_term_redirects SET target_term_id=?,reason=?,created_by=?,created_at=?,active=1 WHERE source_term_id=?',[$target,$reason,$this->actor['id'],date('Y-m-d H:i:s'),$source]);else Db::insert($this->db,'martyr_term_redirects',['source_term_id'=>$source,'target_term_id'=>$target,'reason'=>$reason,'created_by'=>$this->actor['id'],'created_at'=>date('Y-m-d H:i:s')]);Db::query($this->db,'UPDATE protocol_terms SET active=0 WHERE id=?',[$source]);$this->log('term.merge.'.$source,$old,['target'=>$target,'relations_retained'=>true],$reason);});
    }
    public function undo(array $in):void {$source=(int)($in['source_id']??0);$reason=Security::text($in,'reason',2000);if(($in['undo_ack']??'')!=='1')throw new HttpError(422,'بازگردانی نگاشت را صریحاً تأیید کنید.');Db::transaction($this->db,function()use($source,$reason){$row=Db::query($this->db,'SELECT r.*,t.taxonomy FROM martyr_term_redirects r JOIN protocol_terms t ON t.id=r.source_term_id WHERE source_term_id=? AND r.active=1',[$source])->fetch();if(!$row||!Db::query($this->db,'SELECT axis_key FROM martyr_axis_settings WHERE axis_key=?',[$row['taxonomy']])->fetchColumn())throw new HttpError(404,'ادغام فعال پیدا نشد.');Db::query($this->db,'UPDATE martyr_term_redirects SET active=0 WHERE source_term_id=?',[$source]);Db::query($this->db,'UPDATE protocol_terms SET active=1 WHERE id=?',[$source]);$this->log('term.merge.undo.'.$source,$row,['active'=>0],$reason);});}
}
